import { Effect } from "effect"

export interface MediaAsset {
  readonly id: string
  readonly sourceUrl: string
  readonly publishable: boolean
}

export interface Preview {
  readonly assetId: string
  readonly previewUrl: string
}

export interface PreviewRenderer {
  readonly render: (asset: MediaAsset) => Effect.Effect<Preview, Error>
  readonly recordBatch: (count: number) => Effect.Effect<void, Error>
}

export const buildPreviewBatch = (
  assets: ReadonlyArray<MediaAsset>,
  renderer: PreviewRenderer
): Effect.Effect<ReadonlyArray<Preview>, Error> =>
  Effect.gen(function*() {
    const publishable = assets.filter((asset) => asset.publishable)
    const previews = yield* Effect.forEach(
      publishable,
      (asset) => renderer.render(asset),
      { concurrency: 1 }
    )

    yield* renderer.recordBatch(previews.length)
    return previews
  })
